	mSCRIPT_DEFINE_STRUCT_METHOD(mScriptCoreAdapter, write8)
	mSCRIPT_DEFINE_STRUCT_METHOD(mScriptCoreAdapter, write16)
	mSCRIPT_DEFINE_STRUCT_METHOD(mScriptCoreAdapter, write32)
#ifdef ENABLE_DEBUGGERS
