M_TEST_DEFINE(runFrame) {
	SETUP_LUA;
	CREATE_CORE;
	core->reset(core);

	LOAD_PROGRAM(
		"frame = emu:currentFrame()\n"
		"emu:runFrame()\n"
	);

	int i;
	for (i = 0; i < 5; ++i) {
		assert_true(lua->run(lua));
		TEST_VALUE(S32, "frame", i);
	}

	mScriptContextDeinit(&context);
	TEARDOWN_CORE;
}

